from storage_client import get_storage_client
from storage_models import UploadObjectRequest, UploadObjectResponse

def upload_object(
    request: UploadObjectRequest
) -> UploadObjectResponse:
    """Uploads a file or byte stream to Google Cloud Storage."""
    client = get_storage_client()
    bucket = client.bucket(request.bucket_name)
    blob = bucket.blob(request.object_name)

    if request.file_path:
        blob.upload_from_filename(request.file_path)
    elif request.data:
        blob.upload_from_string(request.data)
    else:
        raise ValueError("Either file_path or data must be provided.")

    blob.reload()
    return UploadObjectResponse(
        bucket_name=request.bucket_name,
        object_name=request.object_name,
        size=blob.size,
        self_link=blob.media_link,
    )

from storage_client import get_storage_client
from storage_models import PresignedDownloadRequest, PresignedDownloadResponse

def create_presigned_download_url(
    request: PresignedDownloadRequest
) -> PresignedDownloadResponse:
    """Creates a time-limited signed download URL for a stored object in Google Cloud Storage."""
    client = get_storage_client()
    bucket = client.bucket(request.bucket_name)
    blob = bucket.blob(request.object_name)

    signed_url = blob.generate_signed_url(
        expiration=request.expiration_seconds,
        method='GET'
    )

    return PresignedDownloadResponse(
        signed_url=signed_url
    )

from google.cloud import vision
from google.cloud import storage
import dataclasses
from typing import Optional

@dataclasses.dataclass
class StoredDocumentOcrRequest:
    bucket_name: str
    object_name: str

@dataclasses.dataclass
class StoredDocumentOcrResponse:
    text_content: str

def run_ocr_on_stored_document(
    request: StoredDocumentOcrRequest
) -> StoredDocumentOcrResponse:
    """Runs OCR on a stored document object in Google Cloud Storage using Google Cloud Vision API."""
    client = vision.ImageAnnotatorClient()

    image = vision.Image({
        'source': {'image_uri': f"gs://{request.bucket_name}/{request.object_name}"}
    })

    response = client.text_detection(image=image)
    texts = response.text_annotations

    if texts:
        full_text = texts[0].description
    else:
        full_text = ""

    return StoredDocumentOcrResponse(
        text_content=full_text
    )

from google.cloud import translate
import dataclasses

@dataclasses.dataclass
class StoredTextTranslateRequest:
    text_content: str
    target_language: str
    source_language: str = 'en'

@dataclasses.dataclass
class StoredTextTranslateResponse:
    translated_text: str
    detected_source_language: str

def translate_stored_text(
    request: StoredTextTranslateRequest
) -> StoredTextTranslateResponse:
    """Translates text extracted from a stored document using Google Cloud Translation API."""
    client = translate.TranslationServiceClient()
    parent = f"projects/{client.project_path()}"

    response = client.translate_text(
        parent=parent,
        contents=[request.text_content],
        target_language_code=request.target_language,
        source_language_code=request.source_language,
    )

    translated_text = ""
    detected_source_language = ""

    if response.translations:
        translated_text = response.translations[0].translated_text
        detected_source_language = response.translations[0].detected_language_code

    return StoredTextTranslateResponse(
        translated_text=translated_text,
        detected_source_language=detected_source_language
    )

from vertexai.preview.language_models import TextGenerationModel
import dataclasses

@dataclasses.dataclass
class StoredAssetSummaryRequest:
    text_content: str
    max_output_tokens: int = 256
    temperature: float = 0.2

@dataclasses.dataclass
class StoredAssetSummaryResponse:
    summary_text: str

def summarize_stored_asset(
    request: StoredAssetSummaryRequest
) -> StoredAssetSummaryResponse:
    """Summarizes content extracted from a stored asset using Google Cloud Vertex AI (PaLM 2)."""
    model = TextGenerationModel.from_pretrained("text-bison@001")

    prompt = f"Summarize the following text:\n\n{request.text_content}"

    response = model.predict(
        prompt,
        max_output_tokens=request.max_output_tokens,
        temperature=request.temperature,
    )

    return StoredAssetSummaryResponse(
        summary_text=response.text
    )

from vertexai.preview.language_models import TextEmbeddingModel
import dataclasses
from typing import List

@dataclasses.dataclass
class AssetMetadataEmbeddingRequest:
    text_content: str
    object_name: str
    bucket_name: str

@dataclasses.dataclass
class AssetMetadataEmbeddingResponse:
    embedding: List[float]

def embed_asset_metadata(
    request: AssetMetadataEmbeddingRequest
) -> AssetMetadataEmbeddingResponse:
    """Embeds object metadata and extracted text for search using Google Cloud Vertex AI (Text Embedding API)."""
    model = TextEmbeddingModel.from_pretrained("textembedding-gecko@001")

    # Combine object name, bucket name and text content for a comprehensive embedding
    text_to_embed = f"Bucket: {request.bucket_name}, Object: {request.object_name}, Content: {request.text_content}"

    embeddings = model.get_embeddings([text_to_embed])

    if embeddings:
        return AssetMetadataEmbeddingResponse(
            embedding=embeddings[0].values
        )
    else:
        raise ValueError("Could not generate embedding.")
